from contextlib import contextmanager
from inspect import currentframe
from logging import Logger
from socket import AF_INET, SOCK_STREAM, socket
from typing import Union

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import LOGGER_PORT, REPLY_TIMEOUT, SERVER_HOST, SERVER_PORT
from ta_logcollector.utils.socket_handler import SocketHandler

logger = Logger("LC")
Num = Union[int, float]


@contextmanager
def open_client_socket(host, port, timeout):
    # type: (str, int, Num) -> SocketHandler
    """
    Creates client socket with basic configuration.

    :param host: IP address of host
    :param port: port of host to connect
    :param timeout: timeout in seconds
    :return: socket which will be used to connect to remote end
    """
    _socket = socket(AF_INET, SOCK_STREAM)
    socket_handler = SocketHandler(SERVER_HOST, LOGGER_PORT, _socket, socket_timeout=timeout)
    try:
        socket_handler.connect_socket(host, port)
        yield socket_handler
    finally:
        _socket.close()


def client(message, host=SERVER_HOST, port=SERVER_PORT, socket_timeout=REPLY_TIMEOUT):
    # type: (dict, str, int, Num) -> dict
    """
    TCP client used to communicate with remote server.

    :param message: python dict to be encoded as json.
    :param host: host name or ip address
    :param port: port number
    :param socket_timeout: timeout in seconds for single response
    :return: answer form server json deserialized to dict
    """
    global logger
    logger = get_net_logger(SERVER_HOST, LOGGER_PORT, "{}".format(currentframe().f_code.co_name))
    with open_client_socket(host, port, timeout=socket_timeout) as socket_handler:
        socket_handler.send_msg(message)
        return socket_handler.read_all()


if __name__ == "__main__":
    from ta_logcollector.settings import req_get_state

    cli = client(req_get_state, host=SERVER_HOST, port=SERVER_PORT)
